class ProductOfNumbers {
    vector<long long> products;
public:
    ProductOfNumbers() {
        products.push_back(1);
    }

    void add(int num) {
        if (num == 0) {
            products.clear();
            products.push_back(1);
        } else {
            products.push_back(products.back() * num);
        }
    }

    int getProduct(int k) {
        if (k >= (int)products.size()) {
            return 0;
        }
        return (int)(products.back() / products[products.size() - 1 - k]);
    }
};
